{
  "headline": "FDA's records trace our supply to a plant classified OAI 520 days before the shortage posting",
  "headline_cites": ["D6"],
  "sentences": [
    {
      "text": "Dacarbazine is not on FDA's current shortage list as of 2026-10-21; FDA's history shows an earlier shortage first posted on 2021-10-20, since resolved.",
      "cites": ["D11"]
    },
    {
      "text": "FDA inspection 1123748 at Fresenius Kabi USA, LLC ended 2020-05-18 and was classified OAI with a classification letter dated 2024-05-22, 520 days before FDA posted the shortage on 2021-10-20.",
      "cites": ["D6", "E12"]
    },
    {
      "text": "A second FDA inspection 1174894 at the same plant ended 2022-06-30 and was classified OAI with a classification letter dated 2024-04-30, 253 days after the shortage posting.",
      "cites": ["D7", "E13"]
    },
    {
      "text": "A third FDA inspection 1216183 at the same plant ended 2023-08-24 and was classified VAI with a classification letter dated 2023-10-31, 673 days after the shortage posting.",
      "cites": ["D8", "E14"]
    },
    {
      "text": "Our Corvale General and Corvale East sites both hold dacarbazine 10 mg/mL, 10 mL vials labeled by Fresenius Kabi USA, LLC (NDC 63323012710).",
      "cites": ["E2", "E4"]
    },
    {
      "text": "The ranked transfer option moves 5 vials of 10 mg/mL, 10 mL from Corvale General to Corvale East; Corvale General has 15.8 days on hand and can spare 5 vials while keeping two weeks, and Corvale East has 2.9 days and would reach 4 days.",
      "cites": ["D12"]
    },
    {
      "text": "Check whether the OAI classifications at the Fresenius Kabi plant affected supply during the 2021 shortage period and confirm current supply stability with the manufacturer.",
      "cites": ["D6", "D7", "D11"]
    }
  ]
}
